CREATE TABLE users(user_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), email VARCHAR(120) UNIQUE, password_hash VARCHAR(255), role ENUM('student','admin'));
CREATE TABLE students(student_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT, institution VARCHAR(120), department VARCHAR(80), preferred_role VARCHAR(80), FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE skills(skill_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) UNIQUE, category VARCHAR(40));
CREATE TABLE student_skills(student_skill_id INT AUTO_INCREMENT PRIMARY KEY, student_id INT, skill_id INT, level ENUM('Beginner','Basic','Intermediate','Advanced'), FOREIGN KEY(student_id) REFERENCES students(student_id), FOREIGN KEY(skill_id) REFERENCES skills(skill_id));
CREATE TABLE assessments(assessment_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80), type VARCHAR(40), description TEXT);
CREATE TABLE assessment_results(result_id INT AUTO_INCREMENT PRIMARY KEY, student_id INT, assessment_id INT, score DECIMAL(5,2), level VARCHAR(20), FOREIGN KEY(student_id) REFERENCES students(student_id), FOREIGN KEY(assessment_id) REFERENCES assessments(assessment_id));
CREATE TABLE companies(company_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100), location VARCHAR(80));
CREATE TABLE jobs(job_id INT AUTO_INCREMENT PRIMARY KEY, company_id INT, title VARCHAR(100), description TEXT, FOREIGN KEY(company_id) REFERENCES companies(company_id));
CREATE TABLE job_required_skills(job_skill_id INT AUTO_INCREMENT PRIMARY KEY, job_id INT, skill_id INT, importance DECIMAL(3,2), FOREIGN KEY(job_id) REFERENCES jobs(job_id), FOREIGN KEY(skill_id) REFERENCES skills(skill_id));
CREATE TABLE skill_gap_analysis(gap_id INT AUTO_INCREMENT PRIMARY KEY, student_id INT, job_id INT, skill_id INT, status ENUM('Matched','Developing','Missing'), priority DECIMAL(3,2), FOREIGN KEY(student_id) REFERENCES students(student_id), FOREIGN KEY(job_id) REFERENCES jobs(job_id), FOREIGN KEY(skill_id) REFERENCES skills(skill_id));
CREATE TABLE recommendations(rec_id INT AUTO_INCREMENT PRIMARY KEY, student_id INT, gap_id INT, learning_path TEXT, resource VARCHAR(200), priority DECIMAL(3,2), FOREIGN KEY(student_id) REFERENCES students(student_id), FOREIGN KEY(gap_id) REFERENCES skill_gap_analysis(gap_id));
CREATE TABLE learning_progress(progress_id INT AUTO_INCREMENT PRIMARY KEY, student_id INT, skill_id INT, status ENUM('Not started','In progress','Completed'), completion_date DATE, FOREIGN KEY(student_id) REFERENCES students(student_id), FOREIGN KEY(skill_id) REFERENCES skills(skill_id));
CREATE TABLE job_match(match_id INT AUTO_INCREMENT PRIMARY KEY, student_id INT, job_id INT, match_score DECIMAL(5,2), status VARCHAR(20), FOREIGN KEY(student_id) REFERENCES students(student_id), FOREIGN KEY(job_id) REFERENCES jobs(job_id));
